SELECT

FROM bt_tenant_setting_info a
WHERE a.setting_id = #{id}
  AND a.tenant_id = #{tenantId}
  AND a.status_cd = '00A'

SELECT
FROM bt_tenant_setting_info a WHERE a.status_cd = '00A' AND a.tenant_id = #{query.tenantId}
AND a.func_type IN (#{funcType})
AND a.bot_id = #{query.botId}
AND a.bot_id IS NULL

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_tenant_setting_info a
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.bot_id = #{botId}
  AND a.func_type = 'func_switch'

